using System;using System.Linq;using System.Reflection;using UnityEngine;using LWS.InterstateHauler;
namespace LWS.TruckSnake.Editor {
public static class SnakeNavigationFixtures {
 public static void TerminalEdgeRetainsUniqueSchemaAndReachesMidRoadPickup(){var ai=new SnakeRouteAI();var graph=(LwsRoadGraph)typeof(SnakeRouteAI).GetField("planning",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(ai);graph.graphId="native-terminal-contract";graph.nodes.Add(new LwsRoadNode{nodeId="a",position=Vector3.zero});graph.nodes.Add(new LwsRoadNode{nodeId="b",position=Vector3.forward*100});graph.nodes.Add(new LwsRoadNode{nodeId="target",position=Vector3.forward*40});var source=new LwsRoadEdge{roadId="original-road",segmentId="original-segment",edgeId="original-edge",fromNodeId="a",toNodeId="b",roadClass=LwsRoadClass.LocalRoad,surfaceType=LwsRoadSurfaceType.AsphaltInterstate,oneWay=false,distanceMeters=100,travelCost=100,laneCount=2,laneWidthMeters=4,speedLimitMph=35};for(int z=0;z<=100;z+=10)source.samples.Add(new LwsRoadSample{position=Vector3.forward*z,distanceFromStartMeters=z,forward=Vector3.forward,up=Vector3.up,roadWidthMeters=30});graph.edges.Add(source);var add=typeof(SnakeRouteAI).GetMethod("AddTerminal",BindingFlags.NonPublic|BindingFlags.Instance);add.Invoke(ai,new object[]{source,false,40f,Vector3.forward*40,"target",0});add.Invoke(ai,new object[]{source,true,40f,Vector3.forward*40,"target",0});var validation=graph.Validate();if(!validation.IsValid)throw new Exception(validation.Summary);if(graph.edges.Select(e=>e.roadId).Distinct().Count()!=3||source.roadId!="original-road"||source.samples.Count!=11)throw new Exception("Temporary access changed source geometry or duplicated identifiers.");foreach(var origin in new[]{"a","b"}){var route=new LwsRoutePlanner(LwsNavigationTuning.Default()).PlanRoute(new LwsRouteRequest{originNodeId=origin,destinationNodeId="target",truckRouteRequired=true},graph);if(!route.succeeded||route.waypoints.Count<2||Vector3.Distance(route.waypoints.Last(),Vector3.forward*40)>.001f)throw new Exception("Mid-road pickup did not terminate on its authored position from "+origin+": "+route.message);}}
 public static void ElevatedParallelRouteIsNotTheGroundRoad(){var ai=new SnakeRouteAI();var route=new LwsRouteResult{succeeded=true};for(int z=0;z<100;z+=10)route.waypoints.Add(new Vector3(0,22,z));typeof(SnakeRouteAI).GetField("route",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(ai,route);var query=typeof(SnakeRouteAI).GetMethod("OffRoute",BindingFlags.NonPublic|BindingFlags.Instance);if(!(bool)query.Invoke(ai,new object[]{new Vector3(0,1,30)}))throw new Exception("A truck underneath the bridge was accepted as following the elevated lane.");if((bool)query.Invoke(ai,new object[]{new Vector3(0,22,30)}))throw new Exception("The actual elevated route was rejected.");}
 public static void FloorVelocityCannotQualifyGentleFrontalScrape(){Vector3 incoming=new Vector3(0,-20,3);foreach(var normal in new[]{Vector3.up,Vector3.back})if(SnakeSolidImpact.Qualifies(incoming,Vector3.forward,normal,out _))throw new Exception("Mixed landing and gentle frontal contact must not borrow each other's normal speeds.");if(!SnakeSolidImpact.Qualifies(Vector3.forward*12,Vector3.forward,Vector3.back,out float speed)||speed!=12)throw new Exception("Genuine head-on impact must remain qualifying.");if(SnakeSolidImpact.Qualifies(Vector3.right*20,Vector3.forward,Vector3.left,out _))throw new Exception("Side impact is not a head-on slam.");}

}
